'use strict';

function assertCatalog(catalog) {
  if (catalog === null || typeof catalog !== 'object' || Array.isArray(catalog)) {
    throw new TypeError('catalog must be an object');
  }
}

function listSectors(catalog) {
  assertCatalog(catalog);
  for (const value of Object.values(catalog)) {
    if (!Array.isArray(value)) {
      throw new TypeError('every sector must contain an array');
    }
  }
  return Object.keys(catalog).sort();
}

function listStations(catalog, sector) {
  assertCatalog(catalog);
  if (typeof sector !== 'string') {
    throw new TypeError('sector must be a string');
  }
  if (!Object.prototype.hasOwnProperty.call(catalog, sector)) {
    return [];
  }
  const stations = catalog[sector];
  if (!Array.isArray(stations) || stations.some((station) => typeof station !== 'string')) {
    throw new TypeError('selected sector must contain only string stations');
  }
  return stations;
}

module.exports = { listSectors, listStations };

