'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api).sort(), ['listSectors', 'listStations']);
const { listSectors, listStations } = api;

const catalog = {
  zebra: ['Zulu', 'Zulu', 'Yard'],
  Alpha: ['First'],
  alpha: [],
  '10': ['Ten'],
  '2': ['Two']
};
const snapshot = JSON.parse(JSON.stringify(catalog));

assert.deepStrictEqual(listSectors(catalog), ['10', '2', 'Alpha', 'alpha', 'zebra']);
assert.deepStrictEqual(catalog, snapshot);

const stations = listStations(catalog, 'zebra');
assert.deepStrictEqual(stations, ['Zulu', 'Zulu', 'Yard']);
assert.notStrictEqual(stations, catalog.zebra);
stations.push('Changed');
assert.deepStrictEqual(catalog.zebra, ['Zulu', 'Zulu', 'Yard']);
assert.deepStrictEqual(listStations(catalog, 'alpha'), []);
assert.notStrictEqual(listStations(catalog, 'alpha'), catalog.alpha);
assert.deepStrictEqual(listStations(catalog, 'missing'), []);
assert.deepStrictEqual(catalog, snapshot);

const inherited = Object.create({ inherited: ['Hidden'] });
inherited.own = ['Visible'];
assert.deepStrictEqual(listSectors(inherited), ['own']);
assert.deepStrictEqual(listStations(inherited, 'inherited'), []);
assert.deepStrictEqual(listStations(inherited, 'own'), ['Visible']);

for (const invalidCatalog of [null, undefined, [], 'catalog', 4]) {
  assert.throws(() => listSectors(invalidCatalog), TypeError);
  assert.throws(() => listStations(invalidCatalog, 'x'), TypeError);
}

for (const invalidCatalog of [
  { good: [], bad: 'not-array' },
  { bad: null }
]) {
  assert.throws(() => listSectors(invalidCatalog), TypeError);
}

for (const invalidSector of [null, undefined, 1, {}, []]) {
  assert.throws(() => listStations({ x: [] }, invalidSector), TypeError);
}

assert.throws(() => listStations({ x: 'not-array' }, 'x'), TypeError);
assert.throws(() => listStations({ x: ['valid', 3] }, 'x'), TypeError);
assert.throws(() => listStations({ x: [new String('boxed')] }, 'x'), TypeError);
assert.deepStrictEqual(listStations({ x: 'bad' }, 'absent'), []);

